// Extract order data from webhook payload
const input = items[0].json;

// Determine dispatch type
const isCollection = input.metadata?.dispatchMethod === 'Collection';
const isCourier = input.metadata?.dispatchMethod === 'Courier';

// Build items HTML table
let itemsHtml = '';
for (const item of input.items || []) {
  const serialNumbers = [];

  // Collect serial numbers if present
  if (item.units && item.units.length > 0) {
    item.units.forEach(unit => {
      if (unit.serialNumber) {
        serialNumbers.push(unit.serialNumber);
      }
    });
  }

  const serialInfo = serialNumbers.length > 0 
    ? `<br/><small style="color: #666;">Serial: ${serialNumbers.join(', ')}</small>`
    : '';

  itemsHtml += `
    <tr>
      <td style="padding: 15px 10px; border-bottom: 1px solid #eeeeee;">
        <strong>${item.deviceType}</strong>${serialInfo}
      </td>
      <td style="padding: 15px 10px; border-bottom: 1px solid #eeeeee; text-align: center;">
        ${item.quantityOrdered || item.units?.length || 1}
      </td>
    </tr>
  `;
}

const deliveryInfo = input.deliveryParty === 'Technician' 
  ? `Technician: ${input.technician || 'N/A'}<br/>Region: ${input.region || 'N/A'}<br/>Contractor: ${input.contractorCompany || 'N/A'}`
  : input.deliveryParty === 'Regional Warehouse'
  ? `Regional Warehouse: ${input.region || 'N/A'}`
  : `Recipient: ${input.recipientName || 'N/A'}<br/>Company: ${input.recipientCompanyName || 'N/A'}<br/>Address: ${input.recipientAddress || 'N/A'}<br/>Contact: ${input.recipientContactNumber || 'N/A'}`;

const headerTitle = isCollection ? 'Order Ready for Collection' : 'Order Dispatched';
const alertMessage = isCollection 
  ? `Your order is ready for collection at: ${input.warehouseFulfilling || 'Warehouse'}`
  : isCourier
  ? `Your order has been dispatched via courier and is on its way.`
  : `Your order has been dispatched.`;

return [{
  json: {
    orderId: input.orderId,
    dateOrdered: input.dateOrdered,
    orderedBy: input.orderedBy,
    recipientEmail: input.recipientEmail || input.onBehalfOf || input.orderedBy,
    recipientName: input.recipientName || input.orderedBy,
    deliveryParty: input.deliveryParty,
    totalItems: input.totalItems || input.items?.length || 0,
    totalQuantity: input.totalQuantity,
    itemsHtml: itemsHtml,
    deliveryInfo: deliveryInfo,
    dispatchMethod: input.metadata?.dispatchMethod || 'Standard',
    waybillNumber: input.metadata?.waybillNumber || null,
    warehouseFulfilling: input.warehouseFulfilling || 'Main Warehouse',
    headerTitle: headerTitle,
    alertMessage: alertMessage,
    isCollection: isCollection,
    showWaybill: isCourier && input.metadata?.waybillNumber
  }
}];
